describe('bidi', function()
  itp('resolves the levels Unicode does', function()
    local failed = {}
    for i, case in ipairs(cases) do
      local len = #case[1]
      local cps = ffi.new('int[?]', len)
      local cls = ffi.new('uint8_t[?]', len)
      local orig = ffi.new('uint8_t[?]', len)
      local levels = ffi.new('uint8_t[?]', len)
      for j = 1, len do
        cps[j - 1] = case[1][j]
        cls[j - 1] = lib.bidi_char_class(case[1][j])
        orig[j - 1] = cls[j - 1]
      end
      lib.bidi_resolve_levels(cls, orig, cps, levels, len, case[2])
      for j = 1, len do
        if levels[j - 1] ~= case[3][j] then
          failed[#failed + 1] = ('case %d, character %d: level %d, want %d'):format(
            i,
            j,
            levels[j - 1],
            case[3][j]
          )
          break
        end
      end
    end
    eq({}, failed)
  end)

  itp('puts the characters in the order Unicode does', function()
    local failed = {}
    for i, case in ipairs(cases) do
      local len = #case[1]
      local cps = ffi.new('int[?]', len)
      local cls = ffi.new('uint8_t[?]', len)
      local orig = ffi.new('uint8_t[?]', len)
      local levels = ffi.new('uint8_t[?]', len)
      local order = ffi.new('int[?]', len)
      for j = 1, len do
        cps[j - 1] = case[1][j]
        cls[j - 1] = lib.bidi_char_class(case[1][j])
        orig[j - 1] = cls[j - 1]
      end
      lib.bidi_resolve_levels(cls, orig, cps, levels, len, case[2])
      lib.bidi_visual_order(levels, len, case[2], order)
      for j = 1, len do
        if order[j - 1] ~= case[4][j] then
          failed[#failed + 1] = ('case %d, position %d: character %d, want %d'):format(
            i,
            j,
            order[j - 1],
            case[4][j]
          )
          break
        end
      end
    end
    eq({}, failed)
  end)

  itp('mirrors the brackets that have a counterpart', function()
    eq(string.byte(')'), lib.bidi_char_mirror(string.byte('(')))
    eq(string.byte('('), lib.bidi_char_mirror(string.byte(')')))
    eq(0, lib.bidi_char_mirror(string.byte('a')))
  end)
end)
